#version 300 es
precision highp float;

uniform sampler2D u_image0;
uniform vec2 u_resolution;
uniform float u_float0; // grain amount      [0.0 – 1.0]   typical: 0.2–0.8
uniform float u_float1; // grain size        [0.3 – 3.0]   lower = finer grain
uniform float u_float2; // color amount      [0.0 – 1.0]   0 = monochrome, 1 = RGB grain
uniform float u_float3; // luminance bias    [0.0 – 1.0]   0 = uniform, 1 = shadows only
uniform int   u_int0;   // noise mode        [0 or 1]      0 = smooth, 1 = grainy

in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// Float hash: uint PCG collapses to a constant on ANGLE/GLES (this host).
float hash21(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float hash21(vec2 p, float offset) {
    return hash21(p + vec2(offset * 19.19, offset * 7.77));
}

float toGaussian(vec2 p) {
    float sum = hash21(p, 0.0) + hash21(p, 1.0) + hash21(p, 2.0) + hash21(p, 3.0);
    return (sum - 2.0) * 0.7;
}

float toGaussian(vec2 p, float offset) {
    float sum = hash21(p, offset) + hash21(p, offset + 1.0)
              + hash21(p, offset + 2.0) + hash21(p, offset + 3.0);
    return (sum - 2.0) * 0.7;
}

float smoothNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = toGaussian(i);
    float b = toGaussian(i + vec2(1.0, 0.0));
    float c = toGaussian(i + vec2(0.0, 1.0));
    float d = toGaussian(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float smoothNoise(vec2 p, float offset) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = toGaussian(i, offset);
    float b = toGaussian(i + vec2(1.0, 0.0), offset);
    float c = toGaussian(i + vec2(0.0, 1.0), offset);
    float d = toGaussian(i + vec2(1.0, 1.0), offset);
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void main() {
    vec4 color = texture(u_image0, v_texCoord);
    float luma = dot(color.rgb, vec3(0.2126, 0.7152, 0.0722));
    vec2 grainUV = v_texCoord * u_resolution / max(u_float1, 0.01);
    vec2 grainPixel = floor(grainUV);

    float g;
    vec3 grainRGB;
    if (u_int0 == 1) {
        g = toGaussian(grainPixel);
        grainRGB = vec3(
            toGaussian(grainPixel, 100.0),
            toGaussian(grainPixel, 200.0),
            toGaussian(grainPixel, 300.0)
        );
    } else {
        g = smoothNoise(grainUV);
        grainRGB = vec3(
            smoothNoise(grainUV, 100.0),
            smoothNoise(grainUV, 200.0),
            smoothNoise(grainUV, 300.0)
        );
    }

    float lumWeight = mix(1.0, 1.0 - luma, clamp(u_float3, 0.0, 1.0));
    float strength = u_float0 * 0.15;
    vec3 grainColor = mix(vec3(g), grainRGB, clamp(u_float2, 0.0, 1.0));
    color.rgb += grainColor * strength * lumWeight;
    fragColor0 = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}

